import{_ as a}from"./chunks/safety-distance.DrDRmnVq.js";import{_ as t,o as n,c as o,a5 as i}from"./chunks/framework.CcrBcQWS.js";const m=JSON.parse('{"title":"General Safety Guidelines","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/general-safety-warning-precautions.md","filePath":"manual/safety/general-safety-warning-precautions.md","lastUpdated":1787021357000}'),r={name:"manual/safety/general-safety-warning-precautions.md"};function s(l,e,c,d,g,u){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="general-safety-guidelines" tabindex="-1">General Safety Guidelines <a class="header-anchor" href="#general-safety-guidelines" aria-label="Permalink to &quot;General Safety Guidelines&quot;">​</a></h1><p>General safety rules you must follow when using the RBQ safely. For the meaning of warning symbols, see <a href="/RBQ/nightly/manual/safety/indications.html">Safety Indications</a>.</p><h2 id="general-principles" tabindex="-1">General principles <a class="header-anchor" href="#general-principles" aria-label="Permalink to &quot;General principles&quot;">​</a></h2><ul><li>The RBQ <strong>can carry payloads</strong> and <strong>supply power to</strong> attachments. Attachments affect stability and energy use depending on weight and shape.</li><li>The RBQ is a <strong>dynamic machine</strong>; <strong>unexpected motion</strong> can occur depending on terrain, floor, and obstacles. If anything seems wrong, stop immediately and check the cause.</li></ul><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p> RBQ motion is dynamic; unexpected behavior can occur depending on terrain, floor condition, and obstacles. If anything seems wrong, trigger emergency stop immediately and find the cause. </p></div></div><h2 id="before-operation" tabindex="-1">Before operation <a class="header-anchor" href="#before-operation" aria-label="Permalink to &quot;Before operation&quot;">​</a></h2><ul><li><strong>Trained operators only</strong>: The robot must be operated only by personnel who have read this manual and completed safety training. Read the manual and complete operation and safety training before use.</li><li><strong>Work area</strong>: Provide <strong>enough clear space</strong> for movement, posture correction, and recovery from falls. Do not leave hazards nearby. In tight or cluttered spaces, correction motions may move the robot in unexpected directions; consider guarding if needed.</li></ul><figure><img src="'+a+'" alt="Clear work space and guarding"><figcaption style="text-align:center;">[ Provide sufficient work space; install guarding if necessary. ]</figcaption></figure><h2 id="during-operation" tabindex="-1">During operation <a class="header-anchor" href="#during-operation" aria-label="Permalink to &quot;During operation&quot;">​</a></h2><div class="sb sb-danger"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">DANGER</p><p><strong>While the robot is operating, no people, animals (including pets), or other living beings may enter within 2 m of the robot.</strong> Keep that zone clear while the robot is moving and do not touch the robot.</p></div></div><ul><li><strong>Emergency stop</strong>: See <a href="/RBQ/nightly/manual/safety/emergency-stop-procedures.html">Emergency Stop Procedures</a>.</li><li><strong>No entry</strong>: People and animals (including dogs/pets) must not enter within 2 m of the robot. Do not enter the motion envelope or touch the robot while it is moving.</li><li><strong>Settings</strong>: Periodically verify installation angle, tool settings, and safety settings.</li></ul><h2 id="equipment-and-modifications" tabindex="-1">Equipment and modifications <a class="header-anchor" href="#equipment-and-modifications" aria-label="Permalink to &quot;Equipment and modifications&quot;">​</a></h2><ul><li><strong>Safety I/O only</strong>: Connect safety-related equipment only to dedicated safety I/O ports. Do not connect them to general-purpose I/O.</li><li><strong>No unauthorized modifications</strong>: Do not modify the robot without Rainbow Robotics support. Damage from unauthorized modification is the user’s responsibility.</li></ul><h2 id="heat-and-electricity" tabindex="-1">Heat and electricity <a class="header-anchor" href="#heat-and-electricity" aria-label="Permalink to &quot;Heat and electricity&quot;">​</a></h2><ul><li><strong>Heat</strong>: The robot and controller can get hot after long use. Touch only after they have cooled.</li><li><strong>Electrical safety</strong>: See <a href="/RBQ/nightly/manual/safety/electrical-safety.html">Electrical Safety</a>.</li></ul><h2 id="general-warnings" tabindex="-1">General warnings <a class="header-anchor" href="#general-warnings" aria-label="Permalink to &quot;General warnings&quot;">​</a></h2><ul><li><strong>Payloads</strong>: Payloads affect stability and energy use. Assess risk by weight and shape before attaching.</li><li><strong>Obstacles</strong>: Sudden obstacles can cause avoidance or correction that <strong>accelerates in an unexpected direction</strong>. Keep clear space around the robot.</li><li><strong>Stairs and uneven surfaces</strong>: The robot may change posture abruptly on stairs or uneven floors. Limit speed and approach in those areas.</li><li><strong>Past performance</strong>: Safe operation in the past does not guarantee the same under the same conditions later. Check the environment and settings regularly.</li></ul>',17)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
